sp_widget.client_script:
api.controller = function($scope, $window) {

    var c = this;


    /*
     * =========================================
     * FILTER VARIABLES
     * =========================================
     */

    c.search = "";

    c.roundFilter = "";

    c.statusFilter = "";


    /*
     * =========================================
     * FILTER INTERVIEWS
     * =========================================
     */

    c.filteredInterviews = function() {

        var interviews =
            c.data.interviews || [];


        var search =
            (c.search || "")
            .toLowerCase()
            .trim();


        return interviews.filter(
            function(interview) {


                /*
                 * Search
                 */

                if (search) {

                    var student =
                        (
                            interview.student ||
                            ""
                        ).toLowerCase();


                    var opportunity =
                        (
                            interview.opportunity ||
                            ""
                        ).toLowerCase();


                    var interviewId =
                        (
                            interview.interview_id ||
                            ""
                        ).toLowerCase();


                    if (
                        student.indexOf(search) === -1 &&
                        opportunity.indexOf(search) === -1 &&
                        interviewId.indexOf(search) === -1
                    ) {

                        return false;

                    }

                }


                /*
                 * Round filter
                 */

                if (
                    c.roundFilter &&
                    interview.round !==
                    c.roundFilter
                ) {

                    return false;

                }


                /*
                 * Status filter
                 */

                if (
                    c.statusFilter &&
                    interview.status !==
                    c.statusFilter
                ) {

                    return false;

                }


                return true;

            }
        );

    };


    /*
     * =========================================
     * INITIALS
     * =========================================
     */

    c.getInitials = function(name) {

        if (!name) {

            return "?";

        }


        var parts =
            name.trim().split(/\s+/);


        if (parts.length === 1) {

            return parts[0]
                .substring(0, 2)
                .toUpperCase();

        }


        return (
            parts[0].charAt(0) +
            parts[parts.length - 1].charAt(0)
        ).toUpperCase();

    };


    /*
     * =========================================
     * STATUS CLASS
     * =========================================
     */

    c.getStatusClass = function(status) {

        var value =
            (status || "").toLowerCase();


        if (
            value === "scheduled" ||
            value.indexOf("schedule") >= 0
        ) {

            return "status-scheduled";

        }


        if (
            value === "completed" ||
            value.indexOf("complete") >= 0
        ) {

            return "status-completed";

        }


        if (
            value === "cancelled" ||
            value.indexOf("cancel") >= 0
        ) {

            return "status-cancelled";

        }


        return "status-default";

    };


    /*
     * =========================================
     * REFRESH
     * =========================================
     */

    c.refresh = function() {

        c.server.update().then(
            function(response) {

                /*
                 * Server data automatically
                 * refreshes here.
                 */

            }
        );

    };


    /*
     * =========================================
     * SCHEDULE INTERVIEW
     * =========================================
     *
     * We will create this NEW page next.
     *
     * Do NOT use the old scheduling page.
     */

    c.scheduleInterview = function() {

        $window.location.href =
            "?id=campus360_recruiter_schedule_new";

    };


    /*
     * =========================================
     * VIEW INTERVIEW
     * =========================================
     *
     * For now we will use the same new
     * interview page with the sys_id.
     *
     * We can build the View/Edit page
     * separately after this list works.
     */

    c.viewInterview = function(interview) {

        if (!interview || !interview.sys_id) {

            return;

        }


        $window.location.href =
            "?id=campus360_recruiter_student_profile_new" +
            "&interview_sys_id=" +
            encodeURIComponent(
                interview.sys_id
            );

    };

};

sp_widget.css:
/* =========================================
   MAIN PAGE
   ========================================= */

.interview-page {

  max-width: 1200px;

  margin: 30px auto;

  padding: 0 22px 60px;

  color: #102a56;

}


/* =========================================
   HEADER
   ========================================= */

.page-header {

  background: #ffffff;

  border: 1px solid #e1e7f2;

  border-radius: 18px;

  padding: 28px 32px;

  margin-bottom: 18px;

  display: flex;

  justify-content: space-between;

  align-items: center;

  box-shadow:
    0 8px 25px rgba(30, 55, 90, 0.07);

}


.eyebrow {

  font-size: 11px;

  font-weight: 700;

  letter-spacing: 1.8px;

  color: #5368e8;

}


.page-header h1 {

  margin: 7px 0 5px;

  font-size: 29px;

  color: #102a56;

}


.page-header p {

  margin: 0;

  color: #71809a;

  font-size: 13px;

}


.header-right {

  display: flex;

  align-items: center;

  gap: 28px;

}


.company-info {

  display: flex;

  flex-direction: column;

  gap: 3px;

  min-width: 130px;

}


.company-label {

  font-size: 9px;

  font-weight: 700;

  letter-spacing: 1px;

  color: #7888a3;

}


.company-info strong {

  font-size: 13px;

  color: #102a56;

}


.company-info span:last-child {

  font-size: 12px;

  color: #64748b;

}


/* =========================================
   RECRUITER BAR
   ========================================= */

.recruiter-bar {

  background: #f8f9ff;

  border: 1px solid #e1e5f8;

  border-radius: 12px;

  padding: 14px 20px;

  margin-bottom: 22px;

  display: flex;

  gap: 45px;

}


.recruiter-bar div {

  display: flex;

  flex-direction: column;

  gap: 3px;

}


.recruiter-bar span {

  font-size: 9px;

  font-weight: 700;

  letter-spacing: 1px;

  color: #7888a3;

}


.recruiter-bar strong {

  font-size: 12px;

  color: #24395f;

}


/* =========================================
   BUTTON
   ========================================= */

.btn {

  height: 42px;

  padding: 0 18px;

  border-radius: 8px;

  border: none;

  font-size: 12px;

  font-weight: 600;

  cursor: pointer;

}


.btn-primary {

  background: #5368e8;

  color: #ffffff;

}


.btn-primary:hover {

  background: #4056d5;

}


/* =========================================
   SUMMARY
   ========================================= */

.summary-grid {

  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 16px;

  margin-bottom: 22px;

}


.summary-card {

  background: #ffffff;

  border: 1px solid #e1e7f2;

  border-radius: 14px;

  padding: 20px;

  box-shadow:
    0 5px 18px rgba(30, 55, 90, 0.05);

}


.summary-label {

  font-size: 11px;

  color: #657593;

}


.summary-number {

  font-size: 27px;

  font-weight: 700;

  margin-top: 7px;

  color: #102a56;

}


.summary-text {

  font-size: 10px;

  color: #8a98ae;

  margin-top: 3px;

}


/* =========================================
   FILTERS
   ========================================= */

.filter-card {

  background: #ffffff;

  border: 1px solid #e1e7f2;

  border-radius: 13px;

  padding: 12px;

  display: flex;

  gap: 10px;

  margin-bottom: 28px;

  box-shadow:
    0 5px 18px rgba(30, 55, 90, 0.04);

}


.search-box {

  flex: 1;

  height: 42px;

  border: 1px solid #d7dfec;

  border-radius: 8px;

  display: flex;

  align-items: center;

  padding: 0 12px;

}


.search-icon {

  font-size: 18px;

  margin-right: 8px;

  color: #71809a;

}


.search-box input {

  border: none;

  outline: none;

  width: 100%;

  font-size: 12px;

  color: #24395f;

}


.filter-select {

  width: 180px;

  height: 42px;

  border: 1px solid #d7dfec;

  border-radius: 8px;

  padding: 0 10px;

  background: #ffffff;

  color: #30466d;

  font-size: 12px;

  outline: none;

}


.refresh-btn {

  width: 42px;

  height: 42px;

  border: 1px solid #d7dfec;

  border-radius: 8px;

  background: #ffffff;

  color: #5368e8;

  font-size: 20px;

  cursor: pointer;

}


.refresh-btn:hover {

  background: #f5f7ff;

}


/* =========================================
   SECTION HEADER
   ========================================= */

.section-header {

  display: flex;

  justify-content: space-between;

  align-items: flex-end;

  margin-bottom: 14px;

}


.section-header h2 {

  margin: 5px 0 4px;

  font-size: 18px;

  color: #102a56;

}


.section-header p {

  margin: 0;

  font-size: 11px;

  color: #7888a3;

}


.candidate-count {

  font-size: 11px;

  color: #71809a;

}


/* =========================================
   EMPTY STATE
   ========================================= */

.empty-card {

  background: #ffffff;

  border: 1px solid #e1e7f2;

  border-radius: 16px;

  min-height: 230px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  text-align: center;

}


.empty-icon {

  width: 48px;

  height: 48px;

  border-radius: 12px;

  background: #eef1ff;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 22px;

  margin-bottom: 12px;

}


.empty-card h3 {

  margin: 0 0 6px;

  font-size: 15px;

  color: #102a56;

}


.empty-card p {

  margin: 0;

  font-size: 11px;

  color: #7888a3;

}


/* =========================================
   INTERVIEW LIST
   ========================================= */

.interview-list {

  display: flex;

  flex-direction: column;

  gap: 12px;

}


.interview-card {

  background: #ffffff;

  border: 1px solid #e1e7f2;

  border-radius: 14px;

  padding: 17px 18px;

  display: grid;

  grid-template-columns:
    1.7fr
    1.4fr
    1fr
    1.4fr
    .8fr
    .9fr
    auto;

  align-items: center;

  gap: 18px;

  box-shadow:
    0 5px 18px rgba(30, 55, 90, 0.04);

}


.interview-card:hover {

  border-color: #cbd4ef;

  box-shadow:
    0 8px 22px rgba(30, 55, 90, 0.07);

}


/* =========================================
   CANDIDATE
   ========================================= */

.candidate-section {

  display: flex;

  align-items: center;

  gap: 11px;

}


.candidate-avatar {

  width: 38px;

  height: 38px;

  min-width: 38px;

  border-radius: 50%;

  background: #eef1ff;

  color: #5368e8;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 12px;

  font-weight: 700;

}


.candidate-section h3 {

  margin: 0 0 3px;

  font-size: 12px;

  color: #102a56;

}


.interview-id {

  font-size: 9px;

  color: #8a98ae;

}


/* =========================================
   INFORMATION
   ========================================= */

.info-section {

  display: flex;

  flex-direction: column;

  gap: 4px;

  min-width: 0;

}


.info-label {

  font-size: 8px;

  font-weight: 700;

  letter-spacing: .8px;

  color: #8996aa;

}


.info-section strong {

  font-size: 10px;

  color: #30466d;

  overflow: hidden;

  text-overflow: ellipsis;

  white-space: nowrap;

}


/* =========================================
   STATUS
   ========================================= */

.status-badge {

  display: inline-flex;

  align-items: center;

  width: fit-content;

  padding: 4px 8px;

  border-radius: 20px;

  font-size: 9px;

  font-weight: 600;

}


.status-scheduled {

  background: #eef2ff;

  color: #4d5fe5;

}


.status-completed {

  background: #eaf8f0;

  color: #25804a;

}


.status-cancelled {

  background: #fff0f0;

  color: #c63f3f;

}


.status-default {

  background: #f2f4f7;

  color: #667085;

}


/* =========================================
   ACTION
   ========================================= */

.action-section {

  display: flex;

  justify-content: flex-end;

}


.view-btn {

  height: 34px;

  padding: 0 12px;

  border-radius: 7px;

  border: 1px solid #d1d9e8;

  background: #ffffff;

  color: #5368e8;

  font-size: 10px;

  font-weight: 600;

  cursor: pointer;

}


.view-btn:hover {

  background: #f5f7ff;

}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 1100px) {

  .interview-card {

    grid-template-columns:
      1.5fr 1fr 1fr 1fr;

  }

  .action-section {

    justify-content: flex-start;

  }

}


@media (max-width: 800px) {

  .page-header {

    flex-direction: column;

    align-items: flex-start;

    gap: 20px;

  }


  .header-right {

    width: 100%;

    justify-content: space-between;

  }


  .summary-grid {

    grid-template-columns:
      1fr 1fr;

  }


  .filter-card {

    flex-direction: column;

  }


  .filter-select {

    width: 100%;

  }


  .interview-card {

    grid-template-columns: 1fr 1fr;

  }


  .recruiter-bar {

    flex-wrap: wrap;

  }

}


@media (max-width: 500px) {

  .summary-grid {

    grid-template-columns: 1fr;

  }


  .interview-card {

    grid-template-columns: 1fr;

  }

}

sp_widget.script:
(function() {

    /*
     * =========================================
     * CURRENT PROTOTYPE RECRUITER
     * =========================================
     */

    data.recruiter_name = "Ananya Mehta";
    data.recruiter_id = "RCR001";

    /*
     * TechNova Solutions - CMP001
     */
    var companySysId =
        "e9268662acd303107f44b432e349694b";


    /*
     * =========================================
     * COMPANY INFORMATION
     * =========================================
     */

    data.company_name = "";
    data.company_id = "";

    var companyGR =
        new GlideRecord(
            "x_snc_campus360_company_master"
        );

    if (companyGR.get(companySysId)) {

        data.company_name =
            companyGR.getValue("company_name");

        data.company_id =
            companyGR.getValue("company_id");

    }


    /*
     * =========================================
     * INITIAL DATA
     * =========================================
     */

    data.interviews = [];

    data.counts = {

        scheduled: 0,

        upcoming: 0,

        completed: 0,

        pending: 0

    };


    /*
     * =========================================
     * LOAD INTERVIEWS
     * =========================================
     *
     * IMPORTANT:
     *
     * We don't directly store Company
     * inside Interview.
     *
     * Interview
     *      ↓
     * Opportunity
     *      ↓
     * Company
     *
     * Therefore we filter through:
     *
     * opportunity.company = CMP001
     *
     */


    var interviewGR =
        new GlideRecord(
            "x_snc_campus360_recruiter_interview"
        );


    interviewGR.addQuery(
        "opportunity.company",
        companySysId
    );


    interviewGR.orderByDesc(
        "interview_date"
    );


    interviewGR.query();


    /*
     * =========================================
     * CURRENT DATE/TIME
     * =========================================
     */

    var now =
        new GlideDateTime();


    /*
     * =========================================
     * BUILD INTERVIEW DATA
     * =========================================
     */

    while (interviewGR.next()) {


        var interview = {};


        /*
         * System ID
         */

        interview.sys_id =
            interviewGR.getUniqueValue();


        /*
         * Interview ID
         */

        interview.interview_id =
            interviewGR.getValue(
                "interview_id"
            ) || "";


        /*
         * Candidate
         */

        interview.student =
            interviewGR.getDisplayValue(
                "student"
            ) || "";


        interview.student_sys_id =
            interviewGR.getValue(
                "student"
            ) || "";


        /*
         * Opportunity
         */

        interview.opportunity =
            interviewGR.getDisplayValue(
                "opportunity"
            ) || "";


        interview.opportunity_sys_id =
            interviewGR.getValue(
                "opportunity"
            ) || "";


        /*
         * Interview Round
         */

        interview.round =
            interviewGR.getDisplayValue(
                "interview_round"
            ) || "";


        /*
         * Interview Mode
         */

        interview.mode =
            interviewGR.getDisplayValue(
                "interview_mode"
            ) || "";


        /*
         * Interviewer
         */

        interview.interviewer =
            interviewGR.getValue(
                "interviewer"
            ) || "";


        /*
         * Interview Date
         */

        interview.interview_date =
            interviewGR.getDisplayValue(
                "interview_date"
            ) || "";


        /*
         * Meeting Link
         */

        interview.meeting_link =
            interviewGR.getValue(
                "meeting_link"
            ) || "";


        /*
         * Status
         */

        interview.status =
            interviewGR.getDisplayValue(
                "status"
            ) || "";


        /*
         * Result
         */

        interview.result =
            interviewGR.getDisplayValue(
                "result"
            ) || "";


        /*
         * Feedback
         */

        interview.feedback =
            interviewGR.getValue(
                "feedback"
            ) || "";


        /*
         * Add to array
         */

        data.interviews.push(
            interview
        );


        /*
         * =====================================
         * COUNTERS
         * =====================================
         */

        var status =
            (
                interviewGR.getDisplayValue(
                    "status"
                ) || ""
            ).toLowerCase();


        var result =
            (
                interviewGR.getDisplayValue(
                    "result"
                ) || ""
            ).toLowerCase();


        /*
         * Scheduled
         */

        if (
            status == "scheduled" ||
            status.indexOf("schedule") >= 0
        ) {

            data.counts.scheduled++;

        }


        /*
         * Upcoming
         */

        var interviewDate =
            interviewGR.getValue(
                "interview_date"
            );


        if (
            interviewDate &&
            interviewDate > now.getValue() &&
            status.indexOf("cancel") < 0
        ) {

            data.counts.upcoming++;

        }


        /*
         * Completed
         */

        if (
            status == "completed" ||
            status.indexOf("complete") >= 0
        ) {

            data.counts.completed++;

        }


        /*
         * Pending Result
         */

        if (
            result == "" ||
            result == "pending"
        ) {

            data.counts.pending++;

        }

    }

})();
